def apply(inputs, premises):
    relationship = inputs["employer_relationship_to_worker"]
    exclusion_applies = relationship in premises["covered_relationships_without_age_condition"]
    if not exclusion_applies and relationship in premises["covered_parent_relationships"]:
        exclusion_applies = inputs["worker_age"] < premises["child_age_limit"]
    claim_matches = exclusion_applies == inputs["question_asserts_section_applies"]
    if claim_matches:
        answer = "Entailment"
    else:
        answer = "Contradiction"
    return {"answer": answer}
